<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Notification\Message\Domain\MessageRef;
use Civi\Lughauth\Features\Notification\Message\Application\Service\Visibility\MessageVisibilityService;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageReadGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class MessageRetrieveUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly MessageVisibilityService $visibility,
        private readonly MessageReadGateway $reader
    ) {
    }

    public function allowRetrieve(?MessageRef $ref = null): Allow
    {
        $this->logDebug("Check allow of retrieve usecase for Message");
        $span = $this->startSpan("Check allow of retrieve usecase for Message");
        try {
            $result = $this->dispatcher->dispatch(new MessageRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function hiddenFields(?MessageRef $ref = null): array
    {
        $this->logDebug("Check hidden fields usecase for Message");
        $span = $this->startSpan("Check hidden fields usecase for Message");
        try {
            return $this->visibility->fieldsToHide($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieve(string $uid): MessageRetrieveResult
    {
        $this->logDebug("Run retrieve usecase for Message");
        $span = $this->startSpan("Run retrieve usecase for Message");
        try {
            $ref = new MessageRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve Message');
            }
            if (!$result = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new MessageRetrieveResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
